  1	/**
  2	 * Guard: a multipart recipe's declared `parts` must cover every part the component actually
  3	 * reads off `useMultiStyleConfig`.
  4	 *
  5	 * The failure this catches is silent. Chakra returns a styles object keyed by the recipe's
  6	 * `parts`; reading a key that is not declared yields `undefined`, and `__css={undefined}` is a
  7	 * perfectly legal prop. The element renders unstyled and nothing — not `tsc`, not eslint, not
  8	 * an axe run, not a `play` that only asserts text — reports it.
  9	 *
 10	 * Comparing `parts` against the recipe's own `baseStyle` keys would not catch it: renaming a
 11	 * part in both places at once keeps them consistent with each other and still breaks the
 12	 * component. The component's reads are the only source of truth for what it needs, so this
 13	 * walks the component source.
 14	 *
 15	 * Scope: `overrides/app/components/**` — every co-located `<name>.css.ts`, which since the
 16	 * footer decomposition is where a component's recipe normally lives.
 17	 *
 18	 * It is not a whole-repo guard, and nothing else covers the remainder: the model is strictly
 19	 * sibling-based (a recipe's `parts` are reconciled against the `index.tsx` beside it), so a
 20	 * recipe that does not sit next to its component is out of reach. `theme/components/header.ts`
 21	 * is the only multipart recipe in that position today and is therefore unguarded.
 22	 * `theme/components/recipeGuards.test.ts` does not pick it up either — that suite has no
 23	 * parts-vs-reads check of any kind; it guards bare token keys and recipe namespacing.
 24	 *
 25	 * `READ_RE` recognises only the identifier `styles`, so a second binding in the same component
 26	 * is invisible here: `zimmSubscribeModal/index.tsx` reads `chrome.actions`. That one is
 27	 * deliberately out of scope rather than a gap to close — `chrome` holds *ZimmModal's* recipe,
 28	 * so the sibling model would misattribute `actions` to `zimmSubscribeModal.css.ts`, which
 29	 * correctly does not declare it.
 30	 */
 31	import { describe, expect, test } from 'vitest';
 32	import { existsSync, readFileSync, readdirSync } from 'node:fs';
 33	import path from 'node:path';
 34	
 35	const COMPONENTS = path.resolve(process.cwd(), 'overrides/app/components');
 36	
 37	const walk = (dir: string): string[] =>
 38	  readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
 39	    const full = path.join(dir, entry.name);
 40	    return entry.isDirectory() ? walk(full) : [full];
 41	  });
 42	
 43	/** `parts: ['root', 'label']` — the literal array in a `.css.ts` recipe. */
 44	const PARTS_RE = /\bparts:\s*\[([^\]]*)\]/;
 45	/** `styles.label` and `styles['label']`, the two ways a component reads a resolved part. */
 46	const READ_RE = /\bstyles(?:\.([A-Za-z][A-Za-z0-9]*)|\[\s*'([^']+)'\s*\])/g;
 47	
 48	type MultipartRecipe = {
 49	  name: string;
 50	  recipeFile: string;
 51	  componentFile: string;
 52	  declared: string[];
 53	  read: string[];
 54	  /**
 55	   * Whether the sibling component was found. Recorded rather than thrown on: reading a missing
 56	   * file here would fail *collection*, and vitest reports that as one error for the whole file
 57	   * — taking the vacuity guard below down with it. A guard that disappears when its own
 58	   * assumption breaks is the exact failure this suite exists to prevent.
 59	   */
 60	  componentFound: boolean;
 61	};
 62	
 63	const collectMultipartRecipes = (): MultipartRecipe[] =>
 64	  walk(COMPONENTS)
 65	    .filter((file) => file.endsWith('.css.ts'))
 66	    .flatMap((recipeFile) => {
 67	      const declaredMatch = PARTS_RE.exec(readFileSync(recipeFile, 'utf8'));
 68	      if (!declaredMatch) return []; // single-part recipe — nothing to reconcile
 69	
 70	      const declared = declaredMatch[1]
 71	        .split(',')
 72	        .map((entry) => entry.trim().replace(/^['"]|['"]$/g, ''))
 73	        .filter(Boolean);
 74	
 75	      const componentFile = path.join(path.dirname(recipeFile), 'index.tsx');
 76	      const componentFound = existsSync(componentFile);
 77	      const read = componentFound
 78	        ? [...readFileSync(componentFile, 'utf8').matchAll(READ_RE)].map((match) => match[1] ?? match[2])
 79	        : [];
 80	
 81	      return [
 82	        { name: path.basename(recipeFile, '.css.ts'), recipeFile, componentFile, declared, read, componentFound },
 83	      ];
 84	    });
 85	
 86	const recipes = collectMultipartRecipes();
 87	
 88	describe('multipart recipes declare every part their component reads', () => {
 89	  test.each(recipes.map((recipe) => [recipe.name, recipe] as const))('%s', (_name, recipe) => {
 90	    expect(recipe.componentFound, `no component found at ${recipe.componentFile} for ${recipe.recipeFile}`).toBe(true);
 91	    const undeclared = [...new Set(recipe.read)].filter((part) => !recipe.declared.includes(part));
 92	    expect(undeclared, `${recipe.componentFile} reads parts absent from ${recipe.recipeFile}`).toEqual([]);
 93	  });
 94	
 95	  // Vacuity guard. A suite built by walking the filesystem passes trivially when the walk
 96	  // returns nothing — a moved directory or a renamed suffix would turn this file into a
 97	  // no-op that still reports green. Mirrors recipeGuards.test.ts's own self-test.
 98	  test('the walk actually collected something', () => {
 99	    expect(walk(COMPONENTS).length).toBeGreaterThan(0);
100	    expect(recipes.length).toBeGreaterThan(0);
101	    expect(recipes.every((recipe) => recipe.declared.length > 0)).toBe(true);
102	    expect(recipes.some((recipe) => recipe.read.length > 0)).toBe(true);
103	  });
104	});

