import {readFileSync, readdirSync, existsSync} from 'node:fs';
import path from 'node:path';
const ROOT = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const COMPONENTS = path.join(ROOT, 'overrides/app/components');
const walk = d => readdirSync(d,{withFileTypes:true}).flatMap(e=>{
  const f=path.join(d,e.name); return e.isDirectory()?walk(f):[f];});

// 1. find every style-config call site in production component files
const files = walk(COMPONENTS).filter(f=>/\.tsx?$/.test(f) && !/\.test\.|\.stories\./.test(f));
const CALL = /const\s+(\w+)\s*=\s*(useMultiStyleConfig|useStyleConfig)\(\s*'([^']+)'/g;
for (const f of files) {
  const src = readFileSync(f,'utf8');
  const lines = src.split('\n');
  const calls = [...src.matchAll(CALL)];
  if (!calls.length) continue;
  console.log('\n=== ' + path.relative(ROOT,f));
  for (const c of calls) {
    const ln = src.slice(0,c.index).split('\n').length;
    console.log(`  L${ln}: const ${c[1]} = ${c[2]}('${c[3]}')`);
    // reads for this binding
    const RE = new RegExp(`\\b${c[1]}(?:\\.([A-Za-z][A-Za-z0-9_]*)|\\[\\s*'([^']+)'\\s*\\])`,'g');
    const reads = new Map();
    lines.forEach((l,i)=>{
      for (const m of l.matchAll(RE)) {
        const k = m[1] ?? m[2];
        const commented = /^\s*(\/\/|\*|\/\*)/.test(l);
        if(!reads.has(k)) reads.set(k,[]);
        reads.get(k).push((i+1)+(commented?'(commented)':''));
      }
    });
    console.log('    reads: ' + [...reads.entries()].map(([k,v])=>`${k}@${v.join(',')}`).join('  '));
  }
}
EOF
