        for(;k<src.length;k++){
          const ch=src[k];
          if(ch==='{'||ch==='['||ch==='(')depth++;
          else if(ch==='}'||ch===']'||ch===')'){depth--; if(depth===0)break;}
          else if(depth===1) buf+=ch;
        }
        // strip comments then match `key:`
        buf=buf.replace(/\/\/[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'');
        for(const m of buf.matchAll(/(?:^|\n)\s*['"]?([A-Za-z_$][\w$]*)['"]?\s*:/g)) keys.push(m[1]);
        return [...new Set(keys)];
    }}
  }
  return keys;
}
